@props(['align' => 'inline-start'])

@php
    use Knppy\Ui\Facades\Ui;

    $classes = Ui::classes()
        ->add("flex h-auto cursor-text items-center justify-center gap-2 py-1.5 text-sm font-medium text-muted-foreground select-none group-data-[disabled=true]/input-group:opacity-50 [&>kbd]:rounded-[calc(var(--radius)-5px)] [&>svg:not([class*='size-'])]:size-4")
        ->add(match ($align) {
            'inline-end' => 'order-last pr-3 has-[>button]:mr-[-0.45rem] has-[>kbd]:mr-[-0.35rem]',
            'block-start' => 'order-first w-full justify-start px-3 pt-3 group-has-[>input]/input-group:pt-2.5 [.border-b]:pb-3',
            'block-end' => 'order-last w-full justify-start px-3 pb-3 group-has-[>input]/input-group:pb-2.5 [.border-t]:pt-3',
            default => 'order-first pl-3 has-[>button]:ml-[-0.45rem] has-[>kbd]:ml-[-0.35rem]',
        });
@endphp

<div
    role="group"
    data-slot="input-group-addon"
    data-align="{{ $align }}"
    x-on:click="if (! $event.target.closest('button')) $el.parentElement?.querySelector('input, textarea')?.focus();"
    {{ $attributes->twMerge(['class' => $classes]) }}
>
    {{ $slot }}
</div>

@props([
    'type' => 'button',
    'variant' => 'ghost',
    'size' => 'xs',
])

@php
    use Knppy\Ui\Facades\Ui;

    $classes = Ui::classes()
        ->add('flex items-center gap-2 text-sm shadow-none')
        ->add(match ($size) {
            'sm' => 'h-8 gap-1.5 rounded-md px-2.5 has-[>svg]:px-2.5',
            'icon-xs' => 'size-6 rounded-[calc(var(--radius)-5px)] p-0 has-[>svg]:p-0',
            'icon-sm' => 'size-8 p-0 has-[>svg]:p-0',
            default => "h-6 gap-1 rounded-[calc(var(--radius)-5px)] px-2 has-[>svg]:px-2 [&>svg:not([class*='size-'])]:size-3.5",
        });
@endphp

<x-ui.button
    :type="$type"
    :variant="$variant"
    :size="$size"
    dataSlot="input-group-button"
    {{ $attributes->twMerge(['class' => $classes]) }}
>
    {{ $slot }}
</x-ui.button>
